#!/usr/bin/env python3
"""Generate portable structural-expression encoder controls."""
from expr_dag import LEAN_CODE
CONTROL = 'open Lean H62Interface in\nrun_elab do\n  let _ ← (show GraphM Unit from do\n    let base := mkApp (mkConst ``Nat.succ) (toExpr (3 : Nat))\n    let a ← emit base\n    let b ← emit (mkApp (mkConst ``Nat.succ) (toExpr (3 : Nat)))\n    unless a==b do throw (IO.userError "equal expressions not shared")\n    let pair ← emit (mkApp base base)\n    unless pair>a do throw (IO.userError "missing parent")\n    let x ← emit (.lam `x (mkConst ``Nat) (.bvar 0) .default)\n    let y ← emit (.lam `y (mkConst ``Nat) (.bvar 0) .default)\n    unless x != y do throw (IO.userError "binder names lost")\n    let x ← emit (.letE `x (mkConst ``Nat) (toExpr (0 : Nat)) (.bvar 0) false)\n    let y ← emit (.letE `x (mkConst ``Nat) (toExpr (0 : Nat)) (.bvar 0) true)\n    unless x != y do throw (IO.userError "let annotation lost")\n    let stxA := Syntax.atom .none "x"\n    let stxB := Syntax.atom (.synthetic ⟨0⟩ ⟨1⟩ false) "x"\n    let mdA : MData := ⟨[(`hint,.ofSyntax stxA),(`flag,.ofBool true)]⟩\n    let mdB : MData := ⟨[(`flag,.ofBool true),(`hint,.ofSyntax stxB)]⟩\n    let a ← emit (.mdata mdA base)\n    let b ← emit (.mdata mdB base)\n    unless metadataJson mdA == metadataJson mdB do throw (IO.userError "nonsemantic syntax positions/order not canonical")\n    let mdC : MData := ⟨[(`hint,.ofSyntax (Syntax.atom .none "y")),(`flag,.ofBool true)]⟩\n    let c ← emit (.mdata mdC base)\n    unless a != c do throw (IO.userError "syntax content lost")\n    let duplicate : MData := ⟨[(`hint,.ofSyntax stxB),(`hint,.ofSyntax stxA),(`flag,.ofBool true)]⟩\n    unless metadataJson mdA == metadataJson duplicate do throw (IO.userError "redundant keys not normalized")\n    let _ ← emit (.mdata duplicate base)\n    let parent ← emit (mkApp (mkConst ``Nat.succ) (.mdata mdA base))\n    let _ ← emit (mkApp (mkConst ``Nat.succ) (.mdata duplicate base))\n    let conflict : MData := ⟨[(`hint,.ofSyntax stxA),(`hint,.ofSyntax (Syntax.atom .none "different"))]⟩\n    let refused ← try\n      let _ ← emit (mkApp (mkConst ``Nat.succ) (.mdata conflict base))\n      pure false\n    catch error =>\n      match error with\n      | .userError message => if message == "conflicting metadata keys" then pure true else throw error\n      | _ => throw error\n    unless refused do throw (IO.userError "conflicting metadata accepted through parent memo")\n    IO.println ("DAG-METADATA-ROOTS " ++ toString [a,b,c,parent])\n    IO.println "DAG-CONTROLS PASS"\n    ).run {owner := "control"}\n  pure ()\n'
if __name__ == "__main__":
    print("import Lean\n" + LEAN_CODE + CONTROL, end="")
